import React from "react";
import "./signup.scss";
import "./style.scss";

import { Link } from 'react-router-dom';

// import SignupForm from "./signupform";
import { useState } from "react";
    





export default function Signup() {
    const handleChange=(e)=> {
        const {name,value}=e.target;
        setFormData((previous)=>({
            ...previous,
            [name]:value
        }));
    }

    const handleSubmit=async(e)=> {
    e.preventDefault();
    try {
        const response=await fetch(
            "http://localhost:5000/api/auth/signup",
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(formData)
            }
        );

        const data=await response.json();
        if(!response.ok) {
            alert(data.message);
            return;
        }
        alert(data.message);
        
        console.log("User creaetd:", data.user);
        } catch(error) {
            console.error(error);
            alert("Cannot connect to the server.")
        }
    };

    const [formData, setFormData] = useState({
        username: "",
        email: "",
        phone: ""
    });

    return (
        
        <div className="signuppage">
            <div className="main">
                <div className="header">
                    <div className="sm_infinite">
                        <img src="/assets/sm_infinite.png" alt="sm_infinite" />
                    </div>
                    <div className="login_content">
                        <div className="blank"></div>
                        <div className="btn_log_sign">
                            <button className="login">
                                {/* <div className="log">Log In</div> */}
                                <Link className="log" to="/login">Log In</Link>
                            </button>
                            <button className="signup">
                                <div className="sign"> Sign Up </div>
                            </button>
                        </div>
                    </div>
                </div>

            
                <div className="container">
                    <div className="sub_container">
                        
                            <div className="bg_infinite">
                                <img src="/assets/bg_infinite.png" alt="" />
                            </div>
                            <div className="group">
                                <img src="/assets/Group.png " alt="Group" />
                            </div>
                        
                            <div className="icon_group">
                                <div className="icon">
                                    <img src="/assets/Google.png" alt="Google"/>
                                </div>

                                <div className="icon">
                                    <img src="/assets/firefox.png" alt="firefox"/>
                                </div>

                                <div className="icon">
                                    <img src="/assets/bird.png" alt="bird"/>
                                </div>
                            </div>

                            <div className="subhead">
                                Provide necessary information to proceed
                                with registration or sign up with social media
                            </div>

                            <div className="create_account">
                                Create Account
                            </div>

                            <div className="Typeforms_CTA">
                                <div className="Typeforms">
                                    <div className="typeform">
                                        <div className="Img">
                                            <img src="/assets/user-02.png" alt="" className="user-02" />
                                            <img src="/assets/Divider.png" alt="" className="Divider" />
                                        </div>
                                        <div className="Username">
                                            <input type="text" className="text" placeholder="Username"
                                             onChange={handleChange} value={FormData.username}></input>
                                        </div>
                                    </div>

                                    <div className="typeform">
                                        <div className="Img">
                                            <img src="/assets/mail-02.png" alt="" className="mail-02" />
                                            <img src="/assets/Divider.png" alt="" className="Divider" />
                                        </div>
                                        <div className="Username">
                                            <input type="email" className="text" placeholder="Email"
                                            onChange={handleChange} value={FormData.email}></input>
                                        </div>
                                    </div>
                                </div>

                                <div className="typeform">
                                    <div className="Img">
                                        <img src="/assets/phone.png" alt="" className="phone" />
                                        <img src="/assets/Divider.png" alt="" className="Divider" />
                                    </div>
                                    <div className="Username">
                                        <input type="text" className="text" placeholder="Phone Number      (Optional)" 
                                        onChange={handleChange} value={FormData.phone}></input>
                                    </div>
                                </div>
                                
                                <button type="submit" className="typeform  point Main " onChange={handleSubmit}>
                                    <div className="Proceed">Proceed</div>
                                </button>

                                <button className="typeform point Sub ">
                                    <div className="account">
                                    I already have an account
                                    </div>
                                </button>
                            </div>
                        </div>
                    
                </div>
            </div>
        </div>
    );
}
