import React from "react";
import "./login.scss";
import "./style.scss";
import { useState } from "react";
import API from "../../services/api";

function Login(){
    const [username, setUsername]=useState("");
        const [password, setPassword]=useState("");
        const handleLogin=async()=> {
            try {
                const response=await API.post(
                    "/auth/login",
                    { username, password }
                );

                alert(response.data.message);
            }

            catch(error) {
                alert(error.response.data.message);
            }
        }
    return (
        
        <div className="signuppage">
            <div className="main">
                <div className="header">
                    <div className="sm_infinite">
                        <img src="/assets/sm_infinite.png" alt="sm_infinite" />
                    </div>
                    <div className="login_content">
                        <div className="blank"></div>
                        <div className="btn_log_sign">
                            <button className="login">
                                <div className="log">Log In</div>
                            </button>
                            <button className="signup">
                                <div className="sign"> Sign Up </div>
                            </button>
                        </div>
                    </div>
                </div>

                <div className="container">
                    <div className="sub_container">
                        <div className="Signuptext">Sign up</div>
                        <div className="left">
                            <div className="bg_infinite">
                                <img src="/assets/bg_infinite.png" alt="" />
                            </div>
                        </div>
                        <div className="group">
                            <img src="/assets/Group.png " alt="Group" />
                        </div>

                        <div className="right">
                            <div className="items">
                                <div className="create_account">
                                    Welcome Back
                                </div>

                                <div className="subhead">
                                    Go ahead and log in. Get access to your incredible account!
                                </div>

                                <div className="Typeforms_CTA">
                                    <div className="Typeforms">
                                        <div className="typeform">
                                            <div className="Img">
                                                <img src="/assets/user-02.png" alt="" className="user-02" />
                                                <img src="/assets/Divider.png" alt="" className="Divider" />
                                            </div>
                                            <div className="Username">
                                                <input type="text" className="text" placeholder="Username"></input>
                                            </div>
                                        </div>

                                        <div className="typeform">
                                            <div className="Img">
                                                <img src="/assets/lock-01.png" alt="" className="lock-01" />
                                                <img src="/assets/Divider.png" alt="" className="Divider" />
                                            </div>
                                            <div className="Username">
                                                <input type="password" className="text" placeholder="Password"></input>
                                            </div>
                                        </div>
                                    </div>

                                    <button className="typeform_Main">
                                        <div className="proceed">Log In</div>
                                    </button>

                                    <button className="typeform Sub">
                                        <div className="account">
                                        I forgot my password
                                        </div>
                                    </button>
                                </div>    
                            </div>

                            <div className="icons">
                                <div className="icon_group">
                                    <div className="icon">
                                        <img src="/assets/Google.png" alt="Google"/>
                                    </div>

                                    <div className="icon">
                                        <img src="/assets/firefox.png" alt="firefox"/>
                                    </div>

                                    <div className="icon">
                                        <img src="/assets/bird.png" alt="bird"/>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        
    )
}

export default Login;